using HospitalManagement.Web.Services; using Microsoft.AspNetCore.Mvc;
namespace HospitalManagement.Web.Controllers;
public class DashboardController:Controller{private readonly HospitalApiService api;public DashboardController(HospitalApiService api)=>this.api=api;[HttpGet]public IActionResult Index()=>View();
[HttpPost][IgnoreAntiforgeryToken]public async Task<IActionResult>Data(){var p=await api.PatientsAsync();var d=await api.DoctorsAsync();var a=await api.AppointmentsAsync();var pr=await api.PrescriptionsAsync();if(!p.Ok||!d.Ok||!a.Ok||!pr.Ok)return StatusCode(502,new{message=p.Message??d.Message??a.Message??pr.Message??"Unable to load dashboard."});var today=a.Data!.Where(x=>x.AppointmentDate.Date==DateTime.Today).Take(8).ToList();return Json(new{success=true,data=new{patients=p.Data!.Count,doctors=d.Data!.Count,todayAppointments=a.Data!.Count(x=>x.AppointmentDate.Date==DateTime.Today),pendingPrescriptions=Math.Max(0,a.Data!.Count(x=>x.Status!="Cancelled")-pr.Data!.Count),appointments=today}});}}
